"""latex2qpp: an article's LaTeX to its Q++ file (.qpp), and the check that the Q++ file says what the LaTeX says.

The .qpp file (ASCII, line based, generated; never edited by hand):

    -- Q++ 0.1: generated by qpp/latex2qpp.py from <source>; do not edit
    paper Demo
    alias Tot := eq o ind_k o Scale                 an alias the paper defines (name, slots, expansion)
    lemma lem:S                                     a result: kind and label
      given: a_(1), N in NN, ?{...}                 its statement items (key: Q++ terms, holes ?{latex})
      (sums): a_(j) <= sum i, a_(i) <= N * a_(k)
    proof lem:S                                     its proof lines (item: Q++ word)
      (sums) eq[a_(j) <= sum i, a_(i)] ; ind_l[sum i <= l, a_(i) <= l * a_(k)]

A word is printed from the tokens of qpp/syntax.py: verbs eq neq ind I V and the synonyms alpha beta iota (with _sub and ^v), aliases (P3,
Tot, Hensel_p, with (part) and ^v), references (lem:x(2)), items (k), conditions (U1), data [t, ...],
formulas between factors {t}, o (composition), ; and , (items), ( ) (groups), and the gloss after ' : '.
Terms are Q++ terms (qpp/texmath.py); what the term layer cannot read stays as a hole ?{latex}.

The check (--check): every line and statement item is printed back to LaTeX in the canonical spelling and compared
with the source: 'formal' (no hole), 'same' (the printed LaTeX reads back to the same Q++), 'spelled' (the printed
LaTeX has the source's tokens, up to spaces and braces).

Usage: python3 -m qpp.latex2qpp SOURCE.tex [-o OUT.qpp] [--paper NAME] [--check] [--json REPORT]
"""
import json
import re
import sys
from pathlib import Path

from qpp import syntax as syn
from qpp import texmath as T

RESULT_ENVS = ("theorem", "lemma", "lemmaS", "lemmaP", "lemmaK", "proposition", "corollary", "definition",
               "definitionD", "construction", "example", "exampleW", "remark", "problem", "fact")
ALIAS_ITEM = re.compile(r"^\\mathrm\{([A-Za-z][A-Za-z0-9]*)\}(?:\[(.*?)\])?\s*:=(.*)$", re.S)
KIND = {"lemmaS": "lemma", "lemmaP": "lemma", "lemmaK": "lemma", "definitionD": "definition", "exampleW": "example"}


# ---------------------------------------------------------------------------------------------------------
# formulas

def split_top(s, seps=",;"):
    """split a LaTeX string at top-level separators (outside braces, brackets and parentheses)"""
    out, depth, cur, i = [], 0, "", 0
    while i < len(s):
        c = s[i]
        if c == "\\" and i + 1 < len(s):
            m = re.match(r"\\[A-Za-z]+|\\.", s[i:])
            if m.group(0) in ("\\{", "\\}"):
                depth += 1 if m.group(0) == "\\{" else -1  # a set builder \{...\} is one piece
            cur += m.group(0)
            i += len(m.group(0))
            continue
        if c in "{[(":
            depth += 1
        elif c in "}])":
            depth -= 1
        if c in seps and depth == 0:
            out.append(cur)
            cur = ""
        else:
            cur += c
        i += 1
    out.append(cur)
    return [x for x in (y.strip() for y in out) if x and x not in ("\\", "\\ ")]


FUNCS = set()


def formula(tex, functions=()):
    """a LaTeX formula (or a list of them) as Q++, with holes where the term layer cannot read it"""
    functions = set(functions) | FUNCS
    tex = T.normalize(tex.strip())
    if not tex:
        return ""
    q = T.tex_to_qpp(tex, functions)
    if T.is_formal(q):
        return q
    parts = split_top(tex)
    if len(parts) > 1:
        return ", ".join(T.tex_to_qpp(p, functions) for p in parts)
    return q


def bare_term(tex, functions=()):
    """a formal formula that is a term, not a claim, and names no fact (\\mathrm{Cones}, \\mathcal N are facts)"""
    tex = T.normalize(tex.strip())
    if not T.is_formal(formula(tex, functions)) or len(split_top(tex)) != 1 or \
            re.match(r"\\(mathrm|mathcal|mathsf|mathfrak|operatorname)\b", tex):
        return False
    try:
        x = T.parse_tex(tex, set(functions) | FUNCS)
    except T.Hole:
        return False
    return not (T.is_prop(x) or x[0] in T.PROP_LEAVES)


class DataForm(str):
    """the data of a word, [...]: read with citations (a parenthesized relation cites a hypothesis)"""


def formula_check(tex, functions=()):
    """(formal, same, spelled) for a formula or a list of formulas"""
    if isinstance(tex, DataForm):
        T.DATA_MODE[0] = True
        try:
            return formula_check(str(tex), functions)
        finally:
            T.DATA_MODE[0] = False
    functions = set(functions) | FUNCS
    tex = T.normalize(tex.strip())
    if not tex:
        return True, True, True
    r = T.round_trip(tex, functions)
    if r[0]:
        return r
    parts = split_top(tex)
    if len(parts) > 1:
        rs = [T.round_trip(p, functions) for p in parts]
        return all(x[0] for x in rs), all(x[1] for x in rs), all(x[2] for x in rs)
    return r


LAST_JUXT = []  # the products of a name and a parenthesis in the formal parts of the last item read (texmath.JUXT)


def glosses_of(tex):
    """the glosses of a formal statement item, and its products of a name and a parenthesis (into LAST_JUXT)"""
    T.JUXT.clear()
    gl = len(T.parse_stmt(tex, FUNCS)[1])
    LAST_JUXT.extend(T.JUXT)
    return gl


def stmt_formula(tex):
    """(Q++ of a statement item, (formal, same, spelled), glosses): conventions v1, per part where the item fails"""
    LAST_JUXT.clear()
    tex = tex.strip()
    if not tex:
        return "", (True, True, True), 0
    f, s, p, q = T.stmt_round_trip(tex, FUNCS)
    if f:
        return q, (f, s, p), glosses_of(tex)
    parts = split_top(T.normalize(tex), ";")
    out, checks, gl = [], [], 0
    for part in parts:
        f, s, p, q = T.stmt_round_trip(part, FUNCS)
        checks.append((f, s, p))
        out.append(q if f else "?{" + part.strip() + "}")
        if f:
            gl += glosses_of(part)
    return "; ".join(out), tuple(all(c[i] for c in checks) for i in range(3)), gl


WORD_ROW = re.compile(r"^\\text\{([a-z][a-z ]*)\}\s*:=(.*)$", re.S)


def defrel_lhs(f):
    """the left side L of a row D: L :<=> R (the text between the last context colon and :<=>), or None"""
    m = re.search(r":\s*\\(?:iff|Leftrightarrow)(?![A-Za-z])", f)
    if not m:
        return None
    left, depth, cut = f[:m.start()], 0, 0
    for i, ch in enumerate(left):
        if ch in "{([":
            depth += 1
        elif ch in "})]":
            depth -= 1
        elif ch == ":" and depth == 0 and not left.startswith(":=", i):
            cut = i + 1
    return left[cut:]


def context_of(src):
    """the Q++ of the rows \\sit{context}{...}: names every statement of the paper may use (the dimension n), declared
    once; a statement that uses one gets its declaration first"""
    out = []
    for st in re.findall(r"\\begin\{stmt\}(.*?)\\end\{stmt\}", src, re.S):
        for s in re.finditer(r"\\sit\{", st):
            key, j = syn.balanced(st, s.end() - 1, "{", "}")
            while j < len(st) and st[j] in " \n":
                j += 1
            if key_name(syn.unwrap_text(key).strip()) == "context" and j < len(st) and st[j] == "{":
                f, _ = syn.balanced(st, j, "{", "}")
                q, c, _ = stmt_formula(f)
                if c[0]:
                    out.append(q)
    return out


def context_rows(src):
    """the LaTeX of the rows \\sit{context}{...}"""
    out = []
    for st in re.findall(r"\\begin\{stmt\}(.*?)\\end\{stmt\}", src, re.S):
        for s in re.finditer(r"\\sit\{", st):
            key, j = syn.balanced(st, s.end() - 1, "{", "}")
            while j < len(st) and st[j] in " \n":
                j += 1
            if key_name(syn.unwrap_text(key).strip()) == "context" and j < len(st) and st[j] == "{":
                out.append(syn.balanced(st, j, "{", "}")[0])
    return out


def names_of(src):
    """the names of the rows \\sit{names}{n_y, \\kappa_{\\rm new}, s_{\\min}} of the paper (in any stmt display): each
    is one name, not a member of a family n or a hole; an entry that is not a name with a subscript is ignored"""
    out = set()
    for st in re.findall(r"\\begin\{stmt\}(.*?)\\end\{stmt\}", src, re.S):
        for s in re.finditer(r"\\sit\{", st):
            key, j = syn.balanced(st, s.end() - 1, "{", "}")
            while j < len(st) and st[j] in " \n":
                j += 1
            if key_name(syn.unwrap_text(key).strip()) == "names" and j < len(st) and st[j] == "{":
                f, _ = syn.balanced(st, j, "{", "}")
                for piece in split_top(f, ","):
                    n = T.name_of(piece.strip())
                    if n:
                        out.add(n)
    return out


def vocabulary_of(src):
    """the prelude and the paper's rows \\text{w}:=S, S a set (a noun or an adjective of the paper); the declared
    names of the rows \\sit{names}{...} (vocab "#names")"""
    vocab = dict(T.PRELUDE)
    names = names_of(src)
    if names:
        vocab["#names"] = names
    for f in stmt_items(src):
        m = WORD_ROW.match(f.strip())
        if not m:
            continue
        try:
            s = T.TexParser(T.normalize(split_top(m.group(2), ",;")[0]), FUNCS, vocab).setexpr()
        except T.Hole:
            continue
        if s[0] not in ("set", "setof", "interval", "polyring", "pow", "word") or (s[0] == "pow" and s[1][0] != "set"):
            continue
        w = m.group(1).strip()
        vocab[w] = {"set": s, "plural": w + ("es" if w[-1] in "sxz" or w.endswith("ch") else "s")}
    # relational words: the patterns of the left sides of rows L :<=> R with prose in them (x w of y)
    pats = []
    for f in stmt_items(src):
        lhs = defrel_lhs(f)
        pat = T.textrel_pattern(lhs) if lhs else None
        if pat and pat not in pats:
            pats.append(pat)
    if pats:
        vocab["#textrel"] = pats
    rels = []
    for f in stmt_items(src):
        try:
            parts, _ = T.parse_stmt(f.strip(), FUNCS, vocab)
        except T.Hole:
            continue
        for part in parts:
            if part[0] == "defrel" or (part[0] == "ctx" and part[2][0] == "defrel"):
                rels.append(part)
    if rels:
        vocab["#rel"] = rels
    # operator definitions (a\parallel b:=..., in def:mass or any result): one meaning per paper, read by every
    # statement that uses the operator (Q++ define rows)
    from qpp import qpp2lean
    ops = []
    for f in stmt_items(src):
        try:
            parts, _ = T.parse_stmt(f.strip(), FUNCS, vocab)
        except T.Hole:
            continue
        for part in parts:
            for c in (part[1] if part[0] == "and" else (part,)):
                if qpp2lean.is_op_def(c) and c not in ops:
                    ops.append(c)
    if ops:
        vocab["#opdef"] = ops
    return vocab


# ---------------------------------------------------------------------------------------------------------
# words

def _clean_sub(sub):
    sub = re.sub(r"[{}\s\\]", "", sub)
    return re.sub(r"[^A-Za-z0-9']", "", sub)


def _dual(t):
    return "^v" if t.dual else ""


BY_TEXT = re.compile(r"(?:\\ |\s)*\\text\{by\}(?:\\ |\s)*")


def top_text_by(x):
    """the span (start, end) of the first `\\text{by}` of x at top level, with its spaces, or None"""
    depth = 0
    for k, ch in enumerate(x):
        if depth == 0:
            m = BY_TEXT.match(x, k)
            if m:
                return k, m.end()
        depth += (ch in "{[(") - (ch in "}])")
    return None


def word(expr, functions=()):
    """the Q++ word of a proof line, and the formulas it contains (for the check)"""
    toks = syn.lex(expr)
    out, buf, forms = [], [], []

    terms = {}  # the positions in out of the formulas that are terms
    last_verb = [None]  # the verb just read (its data follows it)

    def flush():
        if buf:
            tex = " ".join(buf)
            forms.append(tex)
            if bare_term(tex, functions):
                terms[len(out)] = tex
            out.append("{" + formula(tex, functions) + "}")
            buf.clear()

    for t in toks:
        k = t.kind
        if k == "MATH":
            buf.append(t.text)
            continue
        if k == "PAREN":
            items, _, _ = syn.parse(t.text)
            if syn.has_word(items):
                flush()
                inner, f2 = word(t.text, functions)
                forms += f2
                out.append("(" + inner + ")" + _dual(t))
            else:
                buf.append("(" + t.text + ")")
            continue
        if k == "DATA" and out and not buf and last_verb[0] in ("LP", "prog"):
            # the data of LP: the prices of the rows, then further data after `;`, each a list of terms; of prog: the
            # prices, then each point as assignments
            T.DATA_MODE[0] = True
            try:
                q = "; ".join(formula(re.sub(r"^(\\ |\s)+", "", x), functions) for x in split_top(t.text, ";"))
            finally:
                T.DATA_MODE[0] = False
            out[-1] += "[" + q + "]"
            continue
        if k == "DATA" and out and not buf and last_verb[0] == "with":
            # the data of with: a clause `HYP \text{by} W`, then the word on the goal after `;`
            parts = split_top(t.text, ";")
            m = re.search(r"(?:\\ |\s)*\\text\{by\}(?:\\ |\s)*", parts[0])
            if not m or len(parts) != 2:
                raise ValueError(f"with[CLAUSE \\text{{by}} W; W']: {t.text!r}")
            hyp = re.sub(r"^(\\ |\s)+", "", parts[0][:m.start()])
            forms.append(hyp)
            q = (formula(hyp, functions) + " by " + word(parts[0][m.end():], functions)[0] + "; "
                 + word(re.sub(r"^(\\ |\s)+", "", parts[1]), functions)[0])
            out[-1] += "[" + q + "]"
            continue
        if k == "DATA" and out and not buf and last_verb[0] == "face":
            # the data of face: the word of the value, then each point (assignments) or the ties, with
            # `\text{by}` and their words, then at m = 2 the word of the gap
            qs = []
            for n_, x in enumerate(split_top(t.text, ";")):
                x = re.sub(r"^(\\ |\s)+", "", x)
                m = top_text_by(x) if n_ else None
                if m is None:
                    qs.append(word(x, functions)[0])
                    continue
                hyp = x[:m[0]]
                forms.append(hyp)
                qs.append(formula(hyp, functions) + " by " + word(x[m[1]:], functions)[0])
            out[-1] += "[" + "; ".join(qs) + "]"
            continue
        if k == "DATA" and out and not buf and last_verb[0] == "chain":
            # the data of chain: the first link `HYP \text{by} W`, each later link a relation, a right side and
            # `\text{by} W`, then the word on the goal (none: V)
            qs = []
            for n_, x in enumerate(split_top(t.text, ";")):
                x = re.sub(r"^(\\ |\s)+", "", x)
                mr = re.match(r"(\\le|\\ge|<|>|=)\s*", x) if n_ else None
                if n_ and not mr:
                    qs.append(word(x, functions)[0])  # the word on the goal
                    continue
                m = re.search(r"(?:\\ |\s)*\\text\{by\}(?:\\ |\s)*", x)
                if not m:
                    raise ValueError(f"chain[A R B \\text{{by}} W; R' C \\text{{by}} W'; ...]: {x!r}")
                hyp = x[:m.start()]
                rel = ""
                if mr:
                    rel = {"\\le": "<=", "\\ge": ">="}.get(mr.group(1), mr.group(1)) + " "
                    hyp = hyp[mr.end():]
                forms.append(hyp)
                qs.append(rel + formula(hyp, functions) + " by " + word(x[m.end():], functions)[0])
            out[-1] += "[" + "; ".join(qs) + "]"
            continue
        if k == "DATA" and out and not buf and last_verb[0] in ("sum", "pow", "div", "take", "logic", "term", "ind",
                                                         "cases", "unfold"):
            # the data of a word of the kernel backend: a word (sum, logic, unfold), or a term and then a word (pow,
            # div, term), or the witnesses as assignments and then a word (take), or the binder and then two words
            # (ind)
            parts = split_top(t.text, ";")
            if last_verb[0] in ("sum", "logic", "unfold"):
                q = word(t.text, functions)[0]
            else:
                q = formula(parts[0], functions) + "".join(
                    "; " + word(re.sub(r"^(\\ |\s)+", "", x), functions)[0] for x in parts[1:])
            out[-1] += "[" + q + "]"
            continue
        if k == "DATA" and out and not buf and last_verb[0] is None and len(split_top(t.text, ";")) > 1 \
                and all(re.search(r"\\text\{by\}", x) or re.match(r"(?:\\ |\s)*\\text\{at\}", x)
                        for x in split_top(t.text, ";")[1:]):
            # the side goals of a reference or an alias after `;`: `HYP \text{by} W`, a clause and the word
            # that proves it
            head, *sides = split_top(t.text, ";")
            T.DATA_MODE[0] = True
            try:
                q = formula(head, functions) if head.strip() else ""
            finally:
                T.DATA_MODE[0] = False
            for x in sides:
                ma = re.match(r"(?:\\ |\s)*\\text\{at\}(?:\\ |\s)*", x)
                if ma:
                    # the point of the reading of a program row: `\text{at}` and the assignments
                    T.DATA_MODE[0] = True
                    try:
                        q += "; at " + formula(x[ma.end():], functions)
                    finally:
                        T.DATA_MODE[0] = False
                    continue
                m = re.search(r"(?:\\ |\s)*\\text\{by\}(?:\\ |\s)*", x)
                if not m:
                    raise ValueError(f"a side goal of a reference: HYP \\text{{by}} W: {x!r}")
                hyp = re.sub(r"^(\\ |\s)+", "", x[:m.start()])
                forms.append(hyp)
                q += "; " + formula(hyp, functions) + " by " + word(x[m.end():], functions)[0]
            out[-1] += "[" + q + "]"
            continue
        if k == "DATA":
            forms.append(DataForm(t.text))
            T.DATA_MODE[0] = True  # a parenthesized relation in data is a citation: \gEq[(x\le1)+2(y\le1)]
            try:
                parts = mid_parts(t.text) if last_verb[0] == "V" else [t.text]
                if len(parts) == 2:
                    # V[written | turned]: the equations after the bar read from their other side
                    w, tt = (formula(x, functions) if x.strip() else "" for x in parts)
                    q = f"{w} | {tt}" if w else f"| {tt}"
                else:
                    q = formula(t.text, functions)
            finally:
                T.DATA_MODE[0] = False
            if out and not buf:
                out[-1] += "[" + q + "]"
            else:
                flush()
                out.append("[" + q + "]")
            continue
        flush()
        last_verb[0] = t.name if k == "VERB" else None
        if k == "VERB":
            sub = _clean_sub(t.sub)
            out.append(t.name + ("_" + sub if sub else "") + _dual(t))
        elif k == "ALIAS":
            sub = _clean_sub(t.sub)
            out.append(t.name + ("_" + sub if sub else "") + (f"({t.part})" if t.part else "") + _dual(t))
        elif k == "REF":
            labs = ",".join(t.labels) or t.name
            out.append(labs + (f"({t.part})" if t.part else "") + _dual(t))
        elif k == "SELF":
            out.append(f"({t.name})" + _dual(t))
        elif k == "COND":
            out.append(f"({t.name})")
        elif k == "O":
            out.append("o")
        elif k == "SEMI":
            out.append(";")
        elif k == "COMMA":
            out.append(",")
        elif k == "GLOSS":
            forms.append(t.text)
            out.append(": " + gloss(t.text, functions))
    flush()
    # |1-a|,|\beta|\le\tfrac14: the lexer splits at the comma, so the relation reaches the last member only; the
    # terms of a run that a comma joins to a formal claim are members of such a list, holes (write the relation for
    # each member)
    listed = set()
    for i in sorted(terms, reverse=True):
        nxt = out[i + 2] if i + 2 < len(out) and out[i + 1] == "," else ""
        if i + 2 in listed or (nxt.startswith("{") and i + 2 not in terms and T.is_formal(nxt)):
            listed.add(i)
    for i in listed:
        out[i] = "{?{" + terms[i].strip() + "}}"
    s = " ".join(out)
    s = re.sub(r" ([;,])", r"\1", s)
    return s, forms


def gloss(text, functions=()):
    q = formula(text, functions)
    return q


# ---------------------------------------------------------------------------------------------------------
# results and statements

def results(src):
    """[(kind, label, [(key, formula)], position, fixes, body)] for the numbered results with a stmt environment or not"""
    out = []
    pat = re.compile(r"\\begin\{(" + "|".join(RESULT_ENVS) + r")\}(\[[^\n]*?\])?(.*?)\\end\{\1\}", re.S)
    for m in pat.finditer(src):
        env, body = m.group(1), m.group(3)
        lab = re.search(r"\\label\{([^}]*)\}", body)
        if not lab:
            continue
        items, fixes, last = [], [], None
        for st in re.findall(r"\\begin\{stmt\}(.*?)\\end\{stmt\}", body, re.S):
            for s in re.finditer(r"\\sit\{", st):
                key, j = syn.balanced(st, s.end() - 1, "{", "}")
                while j < len(st) and st[j] in " \n":
                    j += 1
                if j < len(st) and st[j] == "{":
                    f, j = syn.balanced(st, j, "{", "}")
                    items.append((syn.unwrap_text(key).strip(), f))
                    last = key_name(syn.unwrap_text(key).strip()) or last
                    # \FIX{id} right after an item: a fixture of that item (an empty key continues the previous one)
                    for fm in FIX_AFTER.finditer(st, j):
                        if fm.start() != j:
                            break
                        fixes.append((last, fm.group(1).strip()))
                        j = fm.end()
        # \FIX{id} elsewhere in the result: a fixture of the whole result
        attached = {i for _, i in fixes}
        fixes += [(None, i.strip()) for i in FIX.findall(body) if i.strip() not in attached]
        out.append((KIND.get(env, env), lab.group(1), items, m.start(), fixes, body))
    return out


FIX = re.compile(r"\\FIX\{([^{}]*)\}")
FIX_AFTER = re.compile(r"\s*\\FIX\{([^{}]*)\}")


def stmt_items(src):
    """the formulas of every statement item of the source, inside a result or not (the syntax display); not the
    vocabulary rows of a type row or a context (keys `type`, `given relation`), which vocab_row reads"""
    out = []
    for st in re.findall(r"\\begin\{stmt\}(.*?)\\end\{stmt\}", src, re.S):
        for s in re.finditer(r"\\sit\{", st):
            key, j = syn.balanced(st, s.end() - 1, "{", "}")
            while j < len(st) and st[j] in " \n":
                j += 1
            if j < len(st) and st[j] == "{":
                f = syn.balanced(st, j, "{", "}")[0]
                if key.strip() not in ("type", "given relation"):
                    out.append(f)
    return out


def key_name(key):
    key = re.sub(r"\\\(|\\\)|\$", "", key).strip()
    key = re.sub(r"\\([A-Za-z]+)", r"\1", key)
    return re.sub(r"\s+", " ", key)


# ---------------------------------------------------------------------------------------------------------
# the file and the check

GREEK_ALT = "|".join(sorted(T.GREEK, key=len, reverse=True))
# the head of a name: a bold letter (\mathbf c, \mathbf{c}, \boldsymbol\psi, \ba, \one), or a letter that is not part of a
# command, of a subscript or of a superscript (\gInd_s(2), R_j^\eta(x): s and eta are not heads)
HEAD = (r"(?:\\(?:mathbf|boldsymbol)\s*(?:\{\s*(?P<b>[A-Za-z]|\\(?:" + GREEK_ALT + r"))\s*\}|(?P<b2>[A-Za-z])|(?P<b3>\\(?:"
        + GREEK_ALT + r")))(?![A-Za-z])"
        r"|\\(?P<c>b[a-z]|" + "|".join(sorted(T.BOLD_CMDS, key=len, reverse=True)) + r")(?![A-Za-z])"
        r"|(?<![A-Za-z\\_^])(?P<l>[A-Za-z]|\\(?:" + GREEK_ALT + r"|ell))(?![A-Za-z]))")
# a mark of a name, a superscript that is no power (texmath.MARKS): Y^+, f^*, a^0, w^\circ, g^\prime
MARK = r"\^(?:[+\-*0]|\{\s*(?:[+\-*0]|\\(?:ast|prime|circ))\s*\}|\\(?:ast|prime|circ)(?![A-Za-z]))"
SUFFIX = (r"(?:'*)(?:" + MARK + r")?(?:'*)(?:_(?:\{(?:[^{}]|\{[^{}]*\})*\}|\\?[A-Za-z0-9*]))?(?:'*)(?:" + MARK
          + r")?(?:'*)")
# a declared map may have a command below (\pi_\phi\colon\Z^k\to\Z^m)
MAP_SUFFIX = SUFFIX.replace(r"|\\?[A-Za-z0-9*]))?", r"|\\[A-Za-z]+|[A-Za-z0-9*]))?", 1)
STAR_SUB = re.compile(r"_(?:\*|\{\s*\*\s*\}|\\ast(?![A-Za-z])|\{\s*\\ast\s*\})")
NAMES = "(?P<head>" + HEAD + ")(?P<suffix>" + SUFFIX + ")"
FUNC_DEF = re.compile(NAMES + r"\((?:[^()]{1,40})\)\s*:=")
FUNC_DECL = re.compile("(?P<head>" + HEAD + ")(?P<suffix>" + MAP_SUFFIX + ")"
                       + r"\s*(?:\\colon[^,;$=]{1,40}?|:\s*\\(?:Q|Z|N|R)(?![A-Za-z])[^,;$=]{0,40}?)\\to(?![A-Za-z])")
# applied to a numeral: rho(0); a product with a lone numeral in parentheses is not written
FUNC_NUM = re.compile(NAMES + r"\(\s*-?\d+\s*\)")
# applied to a tuple: weak evidence (t(W, b) may be a scalar times a pair), that makes a parenthesis a hole
FUNC_TUPLE = re.compile(NAMES + r"\((?:(?:[^()\[\],]|\([^()]*\))+,(?:[^()\[\]]|\([^()]*\))*)\)")
NAMES_PLAIN = re.sub(r"\(\?P<\w+>", "(?:", NAMES)
# declared as a number or a vector of numbers: a_h \in \Q, (a,b,k \in \Z_{\ge0}), x\in\Q^n; not a polynomial of
# \Q[y] or a member of another set, which may be a function
SCALAR_DECL = re.compile(r"((?:" + NAMES_PLAIN + r")\s*(?:,\s*(?:" + NAMES_PLAIN + r")\s*)*)(?:\\in\s*(?:\\(?:Q|Z|N)(?![A-Za-z])"
                         r"(?:\s*(?:_\{[^{}]*\}|_\\?[A-Za-z0-9]|\^\{[^{}]*\}|\^\\?[A-Za-z0-9]))*(?!\s*\[)"
                         r"|[\[(]\s*-?[\w.\\{}]+\s*,\s*[-\w.\\{}]+\s*[\])])"
                         r"|(?:\\\s|\s)*\\text\{\s*(?:a|two|the)?\s*(?:mass|masses|integer|integers|rational|rationals)\s*\})")
# a letter after an accent or a font is another name (\dot z, \tilde f, \mathcal F)
ACCENT_BEFORE = re.compile(r"\\(?:dot|ddot|tilde|hat|bar|check|breve|vec|widetilde|widehat|overline|underline|mathcal"
                           r"|mathrm|mathsf|mathfrak|mathbb|mathit|operatorname|rm)\s*\{?\s*$")
CITE = re.compile(r"\\(?:c|C|eq)?ref\{([^}]*)\}")


def head_name(m, text):
    """the key of the name that a match of NAMES reads, as the term layer keys it: the head as the term layer names
    it (b_c for \\mathbf c), and a trailing _ for a member of a family (t_a, rho_{a,d}, x_0: the family t_, rho_,
    x_ is another name than t, rho, x); None after an accent"""
    b = m.group("b") or m.group("b2") or m.group("b3")
    if b:
        name = "b_" + b.lstrip("\\")
    elif m.group("c"):
        c = m.group("c")
        name = T.BOLD_CMDS.get(c, "b_" + c[1:])
    elif ACCENT_BEFORE.search(text[max(0, m.start() - 24):m.start()]):
        return None
    else:
        name = m.group("l").lstrip("\\")
        name = "l" if name == "ell" else name  # \ell is the name l of the term layer
    suffix = m.group("suffix")
    if STAR_SUB.search(suffix):
        # O_*: one name (O_ast), not a member of a family O
        name += "'" * suffix.split("_", 1)[0].count("'")
        return name + "_ast"
    for mk in re.findall(MARK, suffix):
        tok = re.sub(r"[\^{}\s]", "", mk)
        mark = {"+": "_pos", "-": "_neg", "*": "_star", "\\ast": "_star", "0": "_nought", "\\circ": "_circ"}.get(tok)
        if mark:
            name = T.mark_name(name, mark)
    return name + ("_" if "_" in suffix else "")


def math_text(src):
    """the source without the words of \\text{...} (an argument in prose is not an application) and with a pairing
    \\langle w,x\\rangle as one term (its comma does not make a tuple)"""
    src = re.sub(r"\\text\{[^{}]*\}", " ", src)
    return re.sub(r"\\langle(?:[^\\]|\\(?!rangle))*?\\rangle", "0", src)


def heads(regex, src):
    src = math_text(src)
    return {n for n in (head_name(m, src) for m in regex.finditer(src)) if n}


def functions_of(src):
    """letters the text defines as functions (e(a) := ..., rho_{a,d}(x') := ...) or declares as functions
    (F:\\Q^n\\to\\Q, \\theta\\colon\\Q^d\\to\\Q, K\\in\\mathrm{Loss}(n) for a type row of functions), beyond the
    function letters of the term layer. A letter applied to a tuple is not evidence: t(W, b) is a scalar times a
    tuple as often as an application"""
    return heads(FUNC_DEF, src) | heads(FUNC_DECL, src) | typed_functions(src)


# the type rows whose objects are functions (type Loss(n) := lean Point n -> NNRat): set by convert_paper from the
# line `% qpp: maps Loss Map` that qpp2latex writes
FUNC_TYPES = set()


def typed_functions(src, types=None):
    """the names declared in a type row of functions: K,K'\\in \\mathrm{Loss}(n) (types: FUNC_TYPES by default)"""
    types = FUNC_TYPES if types is None else types
    if not types:
        return set()
    # an upright name in the list (K,\mathrm{Ku}\in \mathrm{Potential}(n)) is applied as a function anyway
    name = r"(?:" + NAMES_PLAIN + r"|\\mathrm\{[A-Za-z]+\})"
    pat = re.compile(r"(" + name + r"\s*(?:,\s*" + name + r"\s*)*)\\in\s*\\mathrm\{(?:"
                     + "|".join(re.escape(t) for t in sorted(types)) + r")\}")
    out = set()
    for m in pat.finditer(src):
        g = m.group(1)
        out |= {n for n in (head_name(k, g) for k in re.finditer(NAMES, g)) if n}
    return out


# the vocabulary lines, printed by qpp2latex (vocab_display) as rows of a stmt display keyed by their kind
VOCAB_KEYS = ("word", "define", "type", "relation", "given relation", "alias")
PAIR_TEX = "(\\Q_{\\ge0}\\times\\N_{\\ge1})\\cup\\{\\top\\}"


def tex_term(tex, functions=()):
    """a LaTeX term as a Q++ tree, read whole"""
    p = T.TexParser(T.normalize(tex.strip()), set(functions), T.VOCAB)
    x = p.expr()
    if not p.done():
        raise T.Hole(f"trailing text after the term {tex!r}")
    return x


def tex_item(tex, functions=()):
    """the parts of a LaTeX statement as Q++ trees"""
    parts, _ = T.parse_stmt(T.normalize(tex.strip()), set(functions))
    return parts


def outer(tex, o="(", c=")"):
    """the text inside the brackets that enclose the whole of tex, or None"""
    tex = tex.strip()
    if not (tex.startswith(o) and tex.endswith(c)):
        return None
    inner, j = syn.balanced(tex, 0, o, c)
    return inner if j == len(tex) else None


def top_split(tex, sep):
    """the parts of tex at a separator outside brackets and braces"""
    out, depth, cur, i = [], 0, "", 0
    while i < len(tex):
        ch = tex[i]
        if ch in "({[":
            depth += 1
        elif ch in ")}]":
            depth -= 1
        if depth == 0 and tex.startswith(sep, i) and not (sep[-1].isalpha() and tex[i + len(sep):i + len(sep) + 1].isalpha()):
            out.append(cur)
            cur, i = "", i + len(sep)
            continue
        cur += ch
        i += 1
    return out + [cur]


def tex_type(tex):
    """a LaTeX type (qpp2latex.type_tex) as a Q++ tree"""
    tex = tex.strip()
    if tex.startswith("\\{") and tex.endswith("\\}"):
        # a bundle {P,N\in X,\ op\in Y}: groups of names, each with its type
        out = []
        for grp in top_split(tex[2:-2], ",\\ "):
            names, sep, ty = grp.partition("\\in ")
            if not sep:
                raise T.Hole(f"not a bundle: {tex!r}")
            vs = []
            for nm in top_split(names, ","):
                # a name with its digits (u0, K0) as the printer writes it, or a name the term reader reads
                v = ("var", nm.strip()) if re.fullmatch(r"[A-Za-z][A-Za-z0-9']*", nm.strip()) else tex_term(nm)
                if v[0] != "var":
                    raise T.Hole(f"not a part of a bundle: {nm!r}")
                vs.append(v[1])
            out.append((tuple(vs), tex_type(ty)))
        return ("bundle", tuple(out))
    inner = outer(tex)
    if inner is not None:
        return tex_type(inner)
    parts = top_split(tex, "\\to")
    if len(parts) > 1:
        out = tex_type(parts[-1])
        for q in reversed(parts[:-1]):
            out = ("fun", tex_type(q), out)
        return out
    if tex.startswith("\\mathcal{P}") and outer(tex[len("\\mathcal{P}"):]) is not None:
        return ("app", ("var", "set"), (tex_type(outer(tex[len("\\mathcal{P}"):])),), "call")
    pw = top_split(tex, "^")
    if len(pw) == 2 and outer(pw[1], "{", "}") is not None:
        return ("pow", tex_type(pw[0]), tex_term(outer(pw[1], "{", "}")))
    m = re.fullmatch(r"\\mathrm\{([A-Za-z][A-Za-z0-9]*)\}(\(.*\))?", tex, re.S)
    if m and (m.group(2) is None or outer(m.group(2)) is not None):
        if m.group(2) is None:
            return ("var", m.group(1))
        return ("app", ("var", m.group(1)), tuple(tex_term(a) for a in top_split(outer(m.group(2)), ",")), "call")
    p = T.TexParser(T.normalize(tex), set(), T.VOCAB)
    x = p.setexpr()
    if not p.done() or x[0] != "set":
        raise T.Hole(f"not a type: {tex!r}")
    return x


# the typed words of the rows read so far (\sit{word}{\mathrm{halve}(n,N\in \N)\in ...}), which a define applies
WORD_NAMES = set()


def vocab_row(key, tex, maps=()):
    """the meaning of a vocabulary row \\sit{KEY}{TEX} (qpp2latex.vocab_tree): a set word, a typed word, a define, a
    type row, a relation, a context (key `given relation`), an alias. maps: the names of the type rows of functions,
    whose members (K\\in\\mathrm{Loss}(n)) are applied"""
    tex = tex.strip()
    fs = typed_functions(tex, set(maps))
    if key == "word":
        m = WORD_ROW.match(tex)
        if m:
            p = T.TexParser(T.normalize(m.group(2).strip()), set(), T.VOCAB)
            x = p.setexpr()
            if not p.done():
                raise T.Hole(f"not a set: {m.group(2)!r}")
            return ("word", m.group(1).strip().replace(" ", "_"), x)
        m = re.fullmatch(r"\\mathrm\{([a-z][A-Za-z0-9]*)\}(\(.*)", tex, re.S)
        if m:
            sig, j = syn.balanced(m.group(2), 0, "(", ")")
            res = m.group(2)[j:].strip()
            if res.startswith("\\in"):
                WORD_NAMES.add(m.group(1))
                return ("word", m.group(1), tex_item(sig, fs), tex_type(res[len("\\in"):]))
        raise T.Hole(f"not a word row: {tex!r}")
    if key == "define":
        fs = fs | WORD_NAMES  # a typed word in the body is applied at a point, K(\mathrm{halve}(n,N)(u))
        m = re.fullmatch(r"\\mathrm\{([a-z][A-Za-z0-9]*)\}\(([^()]*)\)\(([^()]*)\)(?:_\{([^{}]*)\})?\s*:=(.*)",
                         tex, re.S)
        if m:  # the body of a typed word at a point: its arguments of function types are applied; a word whose
            # values are tuples at a coordinate, \mathrm{halve}(n,N)(u)_{j}:=t
            args = [tex_term(a, fs) for a in top_split(m.group(2), ",")]
            fs = fs | {a[1] for a in args if a[0] == "var"}
            out = ("define", m.group(1), args, [tex_term(a, fs) for a in top_split(m.group(3), ",")],
                   tex_term(m.group(5), fs))
            return out + (tex_term(m.group(4), fs),) if m.group(4) else out
        return ("define", tex_item(tex, fs))
    if key == "type":
        lhs, sep, val = tex.partition(":=")
        m = re.fullmatch(r"\\mathrm\{([A-Z][A-Za-z0-9]*)\}(?:\((.*)\))?", lhs.strip(), re.S)
        if not sep or not m:
            raise T.Hole(f"not a type row: {tex!r}")
        params = tuple(q.strip() for q in m.group(2).split(",")) if m.group(2) else ()
        return ("type", m.group(1), params, "pair" if val.strip() == PAIR_TEX else tex_type(val))
    if key == "relation":
        pat, sep, body = tex.partition(":\\iff")
        if not sep:
            raise T.Hole(f"not a relation row: {tex!r}")
        args, words = [], []
        for tok in pat.split("\\ "):
            w = re.fullmatch(r"\s*\\text\{(\w+)\}\s*", tok)
            if w:
                words.append(w.group(1))
            else:
                args.append(tex_term(tok, fs))
        return ("relation", [("textrel", tuple(words), tuple(args))], tex_item(body, fs))
    if key == "given relation":
        m = re.fullmatch(r"\\mathrm\{([a-z][A-Za-z0-9]*)\}\((.*)\)", tex, re.S)
        if not m or outer("(" + m.group(2) + ")") is None:
            raise T.Hole(f"not a context row: {tex!r}")
        return ("context", m.group(1), tex_item(m.group(2), fs))
    if key == "alias":
        m = ALIAS_ITEM.match(tex)
        if not m:
            raise T.Hole(f"not an alias row: {tex!r}")
        name = m.group(1) + (f"[{m.group(2)}]" if m.group(2) else "")
        return ("alias", name, " ".join(word(m.group(3))[0].split()))
    raise T.Hole(f"not a vocabulary key: {key}")


def scalars_of(src):
    """names the text declares as numbers or vectors of numbers (a_h\\in\\Q; a,b\\in\\Z_{\\ge0}; t\\in[0,1];
    a\\ \\text{mass}): not functions there"""
    out = set()
    for m in SCALAR_DECL.finditer(re.sub(r"\\langle(?:[^\\]|\\(?!rangle))*?\\rangle", "0", src)):
        g = m.group(1)
        out |= {n for n in (head_name(k, g) for k in re.finditer(NAMES, g)) if n}
    # a vector b_a of numbers has numbers as components: a_h(E) is a product
    out |= {n[2:] + "_" for n in out if n.startswith("b_") and len(n) > 2}
    return out


def scopes(src, results_, contexts):
    """how a name before a parenthesis reads in each result: {label: (functions, numbers, holes)}, by keys
    (head_name). A juxtaposition X(E) is an application if X is a function there, a product if X is a number
    there, and a hole otherwise.
    The functions of a result: the names defined or declared as functions in it (statement or proof), in a result
    it cites, in a context row of the paper, or anywhere in the paper if the paper never declares them as numbers;
    the names it applies to a numeral; the function letters of the term layer; less the names its given declares
    as numbers. Its numbers: the names its given declares as numbers that are not functions there, and the names
    the paper declares as numbers and never uses as functions. Its holes: the names that are both, there or in
    the paper. An item reads a name it declares as a number as one (in_scope)"""
    bodies = {r[1]: r[5] for r in results_}
    givens = {r[1]: " ".join(f for k, f in r[2] if key_name(k) == "given") for r in results_}
    proofs = {}
    for a, b, lab in syn.proof_spans(src):
        proofs[lab] = proofs.get(lab, "") + src[a:b]
    own = {lab: functions_of(body) for lab, body in bodies.items()}
    ctx = set().union(*(functions_of(c) for c in contexts)) if contexts else set()
    defined = functions_of(src)
    evidence = defined | heads(FUNC_NUM, src) | heads(FUNC_TUPLE, src)
    numbers = scalars_of(src)
    letters = T.FUNC_LETTERS | {x + "_" for x in T.FUNC_LETTERS}
    out = {}
    for lab in set(bodies) | set(proofs):
        text = bodies.get(lab, "") + proofs.get(lab, "")
        cited = set()
        for c in CITE.findall(text):
            for x in c.split(","):
                cited |= own.get(re.sub(r"\(.*\)$", "", x.strip()), set())
        here = functions_of(text) | cited | ctx | (defined - numbers) | heads(FUNC_NUM, text) | letters
        given = scalars_of(givens.get(lab, ""))
        fs = here - given
        sc = given - here
        out[lab] = (fs, sc, (evidence | (here & given)) - fs - sc)
    return out


def item_numbers(items):
    """{tag: the names that the statement items of that tag (and the items that continue them) declare as numbers}:
    a proof line of the item (3) reads the numbers that (3) declares"""
    out, tag = {}, None
    for key, f in items:
        tag = key_name(key) or tag
        if tag:
            out[tag] = out.get(tag, set()) | scalars_of(f)
    return out


def convert(src, paper="", source=""):
    """the Q++ text of a paper and the report; the names the paper sets in texmath are restored afterwards"""
    saved = T.save_paper_state()
    try:
        return convert_paper(src, paper, source)
    finally:
        T.restore_paper_state(saved)


def convert_paper(src, paper="", source=""):
    # the contexts of the modules (qpp2latex writes them): their applications are clauses
    for names in re.findall(r"^% qpp: relations (.*)$", src, re.M):
        T.CLAUSE_APPS.update(names.split())
    FUNC_TYPES.clear()
    for names in re.findall(r"^% qpp: maps (.*)$", src, re.M):
        FUNC_TYPES.update(names.split())
    # the patterns of the relation rows (x w y), which the LaTeX prints as prose
    textrels = [tuple(pat.split()) for pat in re.findall(r"^% qpp: textrel (.*)$", src, re.M)]
    src = syn.strip_comments(src)
    # outside a result (words, aliases, context rows): the functions the paper defines or declares; a letter it only
    # applies to a numeral or a tuple is a hole there
    defined = functions_of(src)
    numbers = scalars_of(src)
    evidence = defined | heads(FUNC_NUM, src) | heads(FUNC_TUPLE, src)
    fs = defined - numbers
    outside = (fs, numbers - evidence, evidence - fs - numbers)
    # the maps the paper declares (\pi_\phi\colon\Z^k\to\Z^m): applied by juxtaposition, \pi_\phi\bxi
    T.MAPS.clear()
    T.MAP_CLASH.clear()
    for m in FUNC_DECL.finditer(math_text(src)):
        key = head_name(m, math_text(src))
        try:
            form = T.to_qpp(T.TexParser(T.normalize(m.group("head") + m.group("suffix")), ()).atom())
        except T.Hole:
            continue
        # the map as declared, with its index (\pi_\phi: pi_(phi)); a name the paper declares both a map and a
        # number is neither product nor application before a name
        (T.MAP_CLASH if key in numbers else T.MAPS).add(form)
    in_scope({}, None, outside)
    T.VOCAB.clear()
    T.VOCAB.update(vocabulary_of(src))
    if textrels:
        T.VOCAB["#textrel"] = list(T.VOCAB.get("#textrel", [])) + [t for t in textrels
                                                                   if t not in T.VOCAB.get("#textrel", [])]
    lines = syn.lines_of(src, paper)
    by_label = {}
    for r in lines:
        by_label.setdefault(r["label"], []).append(r)
    defs = syn.alias_defs(src, paper)
    out = [f"-- Q++ 0.1: generated by qpp/latex2qpp.py from {source or 'the source'}; do not edit", f"paper {paper}", ""]
    report = {"lines": [], "items": []}
    for name, d in sorted(defs.items()):
        # a template given in words (a row \sit{templates}{...}) has no formula: its words, as a hole
        words = re.sub(r"^(?:\\\s|\s)+", "", d.get("words") or "")
        w = f"?{{{words}}}" if not d["rhs"].strip() and words else word(d["rhs"])[0]
        slots = re.sub(r"\s+", "", d.get("slots") or "")
        out.append(f"alias {name}[{slots}] := {w}" if slots else f"alias {name} := {w}")
    out.append("")
    for f in stmt_items(src):
        if True:
            m = ALIAS_ITEM.match(f.strip())
            if m:
                slots = [re.sub(r"\\text\{([^}]*)\}.*", r"\1", x.replace("\\ ", " ").strip()).strip()
                         for x in split_top(m.group(2) or "", ";")] if m.group(2) else []
                rhs = split_top(m.group(3), ",")[0]
                w, _ = word(rhs)
                out.append(f"alias {m.group(1)}[{'; '.join(slots)}] := {w}" if slots else f"alias {m.group(1)} := {w}")
    out.append("")
    for w, v in sorted((w, v) for w, v in T.VOCAB.items() if not w.startswith("#")):
        meaning = T.to_qpp(v["set"]) if "set" in v else "lean " + v["lean"]
        out.append(f"word {w.replace(' ', '_')} := {meaning}")
    for r in T.VOCAB.get("#rel", []):
        out.append(f"relation {T.to_qpp(r)}")
    for d in T.VOCAB.get("#opdef", []):
        out.append(f"define {T.to_qpp(d)}")
    for c in context_of(src):
        out.append(f"context {c}")
    out.append("")
    seen = set()
    res = results(src)
    scope = scopes(src, res, context_rows(src))
    ctx_rows = context_rows(src)
    for kind, label, items, _pos, fixes, _body in res:
        seen.add(label)
        out.append(f"{kind} {label}")
        given, in_given, free = [], False, None
        for key, f in with_contexts(items):
            if key_name(key) == "names":
                continue  # a row of declared names (names_of), not an item of the result
            # a core item stands alone (texmath.is_core): its names read as the paper's and its own, not the result's
            core = T.is_core(key_name(key))
            in_scope(*(({}, None) if core else (scope, label)), outside, f)
            in_given = key_name(key) == "given" or (in_given and not key_name(key))
            if in_given:
                given.append(f)
            elif not core:
                # a conclusion on the data alone, which the given only declares, is a condition (texmath.FREE_DATA)
                if free is None:
                    free = free_data(given, ctx_rows)
                T.FREE_DATA[0] = free
            try:
                q, c, gl = stmt_formula(f)
            finally:
                T.FREE_DATA[0] = {}
            report["items"].append({"label": label, "key": key_name(key), "tex": f, "qpp": q,
                                    "formal": c[0], "same": c[1], "spelled": c[2], "glosses": gl,
                                    "misread": sorted({k for k, number in LAST_JUXT if not number})})
            out.append(f"  {key_name(key) or '-'}: {q}")
        for key, fid in fixes:
            out.append(f"  fix {key or '*'} {fid}")
        plines = by_label.get(label, [])
        if plines:
            out.append(f"proof {label}")
            tags = item_numbers(items)
            for r in plines:
                tag = re.sub(r"\\\(|\\\)", "", syn.unwrap_text(r["item"])).strip()
                in_scope(scope, label, outside, r["expr"], tags.get(tag, set()))
                out.append(f"  {line_entry(r, report)}")
        out.append("")
    for label, plines in by_label.items():
        if label in seen:
            continue
        out.append(f"proof {label}")
        for r in plines:
            in_scope(scope, label, outside, r["expr"])
            out.append(f"  {line_entry(r, report)}")
        out.append("")
    in_scope({}, None, outside)
    T.SCOPED[0] = False
    T.MAPS.clear()
    T.MAP_CLASH.clear()
    return "\n".join(out).rstrip() + "\n", report


TYPES = {"NN", "ZZ", "QQ"}  # a declaration x \in \N types x and does not constrain it (\Z_{\ge1} does)


def mid_parts(x):
    """the data of \\gV[written \\mid turned] at its `\\mid` outside brackets: [written, turned], or [x]"""
    depth = 0
    for i in range(len(x)):
        ch = x[i]
        depth += (ch in "([{") - (ch in ")]}")
        if depth == 0 and x.startswith("\\mid", i) and not x[i + 4:i + 5].isalpha():
            return [x[:i].strip(), x[i + 4:].strip()]
    return [x]


def free_data(given, raw=()):
    """the names a given declares as data (n,\\beta\\in\\N) that nothing constrains: no hypothesis of the given
    names them, they are not defined, no definition of a constrained name uses them, and no clause with a hole and
    no text of raw (the context rows) mentions them. A conclusion on these names alone is a condition (texmath
    FREE_DATA)"""
    decl, hyps, defs, holes, hole_defs = {}, set(), [], list(raw), []

    def clause(c):
        """a clause of a part with a hole: read alone; a definition with a hole (x:=E) constrains the names of E
        only if x is constrained; any other clause with a hole constrains every name it mentions"""
        try:
            for x in T.parse_stmt(c, FUNCS)[0]:
                walk(x)
            return
        except T.Hole:
            pass
        lhs, sep, rhs = c.partition(":=")
        if sep:
            try:
                hole_defs.append((T.data_atoms(T.parse_tex(lhs.strip(), FUNCS)), rhs))
                return
            except T.Hole:
                pass
        holes.append(c)

    def walk(x):
        if x[0] == "and":
            for y in x[1]:
                walk(y)
        elif x[0] == "decl" and x[2][:1] == ("set",) and x[2][1] in TYPES:
            for n in x[1]:
                for a in T.data_atoms(n):
                    decl[a] = (n, x[2][1])
        elif x[0] == "def":
            defs.append((T.data_atoms(x[1]), T.data_atoms(x[2])))
        else:
            hyps.update(T.data_atoms(x))

    for tex in given:
        for part in split_top(T.normalize(tex), ";"):
            try:
                xs, _ = T.parse_stmt(part, FUNCS)
            except T.Hole:
                for c in split_top(part, ","):
                    clause(c)
                continue
            for x in xs:
                walk(x)
    flat = lambda h: re.sub(r"_\{([A-Za-z0-9])\}", r"_\1", h)  # noqa: E731
    mentions = {}
    for a, (n, _ty) in decl.items():
        t = flat(T.to_tex(n))
        mentions[a] = re.compile(r"(?<![A-Za-z\\])" + re.escape(t) + r"(?![A-Za-z0-9'_^])")
    # every definition, read or with a hole: (the names it defines, the declared names its right side uses)
    defs += [(lhs, {a for a, m in mentions.items() if m.search(flat(rhs))}) for lhs, rhs in hole_defs]
    defined = set().union(*(lhs for lhs, _ in defs))
    bound = set(hyps)
    grew = True
    while grew:
        grew = False
        for lhs, rhs in defs:
            if lhs & bound and not rhs <= bound:
                bound |= rhs
                grew = True
    return {a: decl[a][1] for a, m in mentions.items()
            if a not in bound and a not in defined and not any(m.search(flat(h)) for h in holes)}


def in_scope(scope, label, outside, item=None, numbers=()):
    """the reading of a name before a parenthesis (scopes) in the result, and in the item being read: a name the
    item declares as a number is one there, unless it is a function of the result (then it is a hole: P a mass
    and P(\\mathbf a) in one item); outside a result: the functions the paper defines or declares and never
    declares as numbers, and the numbers it never uses as functions"""
    global FUNCS
    fs, sc, holes = scope.get(label, outside)
    local = set(numbers) | (scalars_of(item) if item else set())
    # a name the item declares in a type of functions (M\in \mathrm{Sizes}(n,n)) is a function there, unless the
    # item declares it as a number too
    maps = (typed_functions(item) if item else set()) - local
    FUNCS = (fs | maps) - local
    T.SCOPED[0] = True
    T.SCALARS.clear()
    T.SCALARS.update((sc - maps) | (local - fs))
    T.ELSEWHERE.clear()
    T.ELSEWHERE.update((holes - maps) | (local & fs))


CTX_END = re.compile(r"(?:\\\s|\s|\\,|\\;|\\quad|\\qquad)*:(?:\\\s|\s)*$")


def with_contexts(items):
    """an item that ends with a colon is the context of the items that continue it (empty key): each of their
    parts reads  context : part,  under the key of the context item"""
    out, ctx = [], None
    for key, f in items:
        if key_name(key):
            if ctx is not None and not ctx[2]:
                out.append((ctx[0], ctx[1]))  # a context that nothing continues: as written
            ctx = None
            m = CTX_END.search(f)
            if m and not f.rstrip().endswith("::"):
                ctx = [key, f[:m.start()], False]
                continue
            out.append((key, f))
            continue
        if ctx is not None:
            parts = split_top(f, ";")
            out.append((ctx[0] if not ctx[2] else key, ";\\ ".join(f"{ctx[1]}:\\ {p.strip()}" for p in parts if p.strip())))
            ctx[2] = True
            continue
        out.append((key, f))
    if ctx is not None and not ctx[2]:
        out.append((ctx[0], ctx[1]))
    return out


def line_entry(r, report):
    w, forms = word(r["expr"])
    T.JUXT.clear()
    checks = [formula_check(f) for f in forms]
    formal = "?{" not in w
    report["lines"].append({"label": r["label"], "item": r["item"], "tex": r["expr"], "qpp": w, "formal": formal,
                            "same": formal and all(c[1] for c in checks),
                            "spelled": formal and all(c[2] for c in checks),
                            "misread": sorted({k for k, number in T.JUXT if not number}) if formal else []})
    item = syn.unwrap_text(r["item"]).strip()
    item = re.sub(r"\\\(|\\\)", "", item)
    return f"{item} {w}" if item else w


# the counting convention of the full compilation (one for both papers): a statement item is a \sit row of a stmt
# display whose key is none of these (origin lines, classical and reference rows, names rows are no mathematics of
# the result)
UNCOUNTED_KEYS = ("origin", "classical", "reference", "names")


def counted(report):
    """the statement items of the report under the counting convention (UNCOUNTED_KEYS left out)"""
    return [it for it in report["items"] if it["key"] not in UNCOUNTED_KEYS]


def summary(report):
    def count(xs):
        n = len(xs)
        f = sum(x["formal"] for x in xs)
        s = sum(x["same"] for x in xs)
        p = sum(x["spelled"] for x in xs)
        return {"n": n, "formal": f, "same": s, "spelled": p}
    res = {}
    for it in report["items"]:
        res.setdefault(it["label"], {"stmt": True, "proof": True})
        res[it["label"]]["stmt"] &= it["formal"]
    for ln in report["lines"]:
        res.setdefault(ln["label"], {"stmt": True, "proof": True})
        res[ln["label"]]["proof"] &= ln["formal"]
    has_items = {it["label"] for it in report["items"]}
    has_lines = {ln["label"] for ln in report["lines"]}
    st = {k for k, v in res.items() if v["stmt"] and k in has_items}
    pr = {k for k, v in res.items() if v["proof"] and k in has_lines}
    items = counted(report)
    compiled = {}
    for it in items:
        compiled[it["label"]] = compiled.get(it["label"], True) and it["formal"] and it["same"]
    return {"lines": count(report["lines"]), "items": count(report["items"]),
            "results": {"n": len(res), "with statement items": len(has_items), "formal statement": len(st),
                        "with proof lines": len(has_lines), "formal proof": len(pr), "both": len(st & pr)},
            "statement items": {**count(items), "results": len(compiled),
                                "results fully compiled": sum(compiled.values())},
            "misread": misread(report)}


def misread(report):
    """the items and lines in which a name before a parenthesis was read as a product although the scope does not
    declare it a number (an application is never printed back as a product); 0 when the check passes"""
    return sum(bool(x.get("misread")) for x in report["items"] + report["lines"])


def main(argv):
    check = "--check" in argv
    argv = [a for a in argv if a != "--check"]
    rep_out = None
    if "--json" in argv:
        i = argv.index("--json")
        rep_out = argv[i + 1]
        argv = argv[:i] + argv[i + 2:]
    outs = {}
    src = Path(argv[0])
    paper = argv[argv.index("--paper") + 1] if "--paper" in argv else src.stem
    text, rep = convert(src.read_text(encoding="utf-8"), paper, str(src))
    outs[paper] = (text, rep)
    if "-o" in argv:
        Path(argv[argv.index("-o") + 1]).write_text(text, encoding="utf-8")
    elif not check:
        sys.stdout.write(text)
    rc = 0
    if check:
        for p, (_, rep) in outs.items():
            print(p, json.dumps(summary(rep)))
            t = summary(rep)["statement items"]
            print(p, "statement items (keys origin, classical, reference, names left out): "
                  f"{t['n']} items, {t['formal']} formal, {t['same']} same, {t['spelled']} spelled; "
                  f"{t['results fully compiled']} of {t['results']} results fully compiled")
            bad = [(x["label"], x.get("key", x.get("item")), x["misread"]) for x in rep["items"] + rep["lines"]
                   if x.get("misread")]
            print(p, "no application read as a product:", "pass" if not bad else f"FAIL {bad[:10]}")
            rc |= bool(bad)
    if rep_out:
        Path(rep_out).write_text(json.dumps({p: {"summary": summary(r), **r} for p, (_, r) in outs.items()},
                                            indent=1, ensure_ascii=False), encoding="utf-8")
    return rc


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
